// Preview is the resolver for the preview field.
func (r *nodeResolver) Preview(ctx context.Context, obj *Node) (*PreviewInfo, error) {
	if obj.Kind != NodeKindFile {
		return &PreviewInfo{Kind: PreviewKindNone}, nil
	}
	// 列表路径零查询(缩略图乐观签发);详情由单节点查询走 ForNode
	if obj.InList {
		return gqlPreview(r.Previews.ForList(ctx, obj.Name, obj.Sha256, obj.Mime, obj.Size)), nil
	}
	info, err := r.Previews.ForNode(ctx, obj.Name, obj.Sha256, obj.Mime, obj.Size)
	if err != nil {
		return nil, err
	}
	out := gqlPreview(info)
	if info.Kind == service.PvVideo {
		subs, err := r.subtitlesFor(ctx, obj)
		if err != nil {
			return nil, err
		}
		out.Subtitles = gqlSubtitles(subs)
	}
	return out, nil
}

// DownloadURL is the resolver for the downloadUrl field.
func (r *nodeResolver) DownloadURL(ctx context.Context, obj *Node) (*string, error) {
	if obj.Kind != NodeKindFile || obj.DeletedAt != nil {
		return nil, nil
	}
	nid, err := parseID(obj.ID)
	if err != nil {
		return nil, err
	}
	ident, err := r.requireNodeAccess(ctx, nid)
	if err != nil {
		return nil, err
	}
	u, err := r.Uploads.DownloadURL(ctx, ident.UserID, nid)
	if err != nil {
		return nil, err
	}
	// 访客下载单个文件也算一次访问(属主自己下载不算)。
	// 语义是"签发了下载 URL"而不是"字节传完了" —— 下载走预签名直连对象存储,
	// 服务端观测不到完成时刻。
	if ident.Scope != service.ScopeUser {
		if sid, ok := service.ShareScopeID(ident.Scope); ok {
			r.Shares.RecordVisit(ctx, sid, "download")
		}
	}
	return &u, nil
}

// PlayProgress is the resolver for the playProgress field.
func (r *nodeResolver) PlayProgress(ctx context.Context, obj *Node) (*PlayProgress, error) {
	if obj.Kind != NodeKindFile || obj.InList {
		return nil, nil
	}
	ident, err := httpx.IdentityFrom(ctx)
	if err != nil || ident.Scope != service.ScopeUser {
		return nil, nil // 访客没有进度
	}
	nid, err := parseID(obj.ID)
	if err != nil {
		return nil, err
	}
	p, err := r.Media.Progress(ctx, ident.UserID, nid)
	if err != nil {
		return nil, err
	}
	return gqlPlayProgress(p), nil
}

// Path is the resolver for the path field.
func (r *nodeResolver) Path(ctx context.Context, obj *Node) (*string, error) {
	if obj.DeletedAt != nil {
		return nil, nil
	}
	ident, err := httpx.IdentityFrom(ctx)
	if err != nil || ident.Scope != service.ScopeUser {
		return nil, nil // 访客看不到属主的目录结构
	}
	nid, err := parseID(obj.ID)
	if err != nil {
		return nil, err
	}
	p, err := r.Nodes.Path(ctx, ident.UserID, nid)
	if err != nil {
		return nil, nil // 不是自己的、已不在:位置留空,不让整个查询失败
	}
	return &p, nil
}

